def rop_partition(resources, tasks, m):
    sync_procs = assign_sync_procs(resources, m)
    for task in tasks:
        for r in task.resources:
            task.cs[r] = sync_procs[r]
        task.ncs = assign_app_procs(task, m - len(sync_procs))

def apply_re(job, prev_job):
    if prev_job.running_on_partition(job.proc):
        job.release = max(job.arrival, prev_job.finish)
